/**
 * @swagger
 * tags:
 *   - name: Master
 *     description: |
 *       Job categories, institution types, states and cities. Reads are public (no token needed);
 *       create, update and delete are admin only. Codes are generated by the server.
 *
 * components:
 *   schemas:
 *     MasterJobCategory:
 *       type: object
 *       properties:
 *         code: { type: string, example: "EDJCAT00001" }
 *         name: { type: string, example: "Primary Teacher" }
 *         status: { type: string, enum: [active, inactive] }
 *     MasterInstitutionType:
 *       type: object
 *       properties:
 *         code: { type: string, example: "EDJITY00001" }
 *         name: { type: string, example: "School" }
 *         status: { type: string, enum: [active, inactive] }
 *     MasterState:
 *       type: object
 *       properties:
 *         code: { type: string, example: "EDJSTA00026" }
 *         name: { type: string, example: "Uttar Pradesh" }
 *         status: { type: string, enum: [active, inactive] }
 *     MasterCity:
 *       type: object
 *       properties:
 *         code: { type: string, example: "EDJCTY00150" }
 *         name: { type: string, example: "Noida" }
 *         state_code: { type: string, example: "EDJSTA00026" }
 *         state_name: { type: string, example: "Uttar Pradesh" }
 *         status: { type: string, enum: [active, inactive] }
 */

/**
 * @swagger
 * /api/v1/master/job-categories:
 *   get:
 *     summary: List job categories (public, no token needed)
 *     tags: [Master]
 *     parameters:
 *       - { in: query, name: page, schema: { type: integer, default: 1 } }
 *       - { in: query, name: limit, schema: { type: integer, default: 100, maximum: 500 } }
 *       - { in: query, name: search, schema: { type: string }, description: Partial match on name }
 *       - { in: query, name: status, schema: { type: string, enum: [active, inactive, all], default: active } }
 *     responses:
 *       200:
 *         description: resData holds data + pagination, ordered by name
 *         content:
 *           application/json:
 *             schema:
 *               allOf:
 *                 - $ref: '#/components/schemas/SuccessResponse'
 *                 - type: object
 *                   properties:
 *                     resData:
 *                       type: object
 *                       properties:
 *                         data: { type: array, items: { $ref: '#/components/schemas/MasterJobCategory' } }
 *                         pagination: { $ref: '#/components/schemas/PaginationResponse' }
 *       400: { description: Invalid query parameters, content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *   post:
 *     summary: Create a job category (admin)
 *     tags: [Master]
 *     security:
 *       - bearerAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [name]
 *             properties:
 *               name: { type: string }
 *               status: { type: string, enum: [active, inactive] }
 *           example: { name: "New job category" }
 *     responses:
 *       200: { description: Created; resData is the new job category, content: { application/json: { schema: { $ref: '#/components/schemas/SuccessResponse' } } } }
 *       400: { description: "Validation error, job_category_exists (names are unique, deleted rows included)", content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *       401: { description: Missing or invalid token, content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *       403: { description: Not an admin, content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 */

/**
 * @swagger
 * /api/v1/master/job-categories/{categorycode}:
 *   parameters:
 *     - { in: path, name: categorycode, required: true, schema: { type: string, example: "EDJCAT00001" } }
 *   get:
 *     summary: Get a job category by code (public, no token needed)
 *     tags: [Master]
 *     responses:
 *       200:
 *         description: The job category
 *         content:
 *           application/json:
 *             schema:
 *               allOf:
 *                 - $ref: '#/components/schemas/SuccessResponse'
 *                 - type: object
 *                   properties:
 *                     resData: { $ref: '#/components/schemas/MasterJobCategory' }
 *       404: { description: Not found (job_category_not_found), content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *   patch:
 *     summary: Update a job category (admin)
 *     tags: [Master]
 *     security:
 *       - bearerAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             minProperties: 1
 *             properties:
 *               name: { type: string }
 *               status: { type: string, enum: [active, inactive] }
 *           example: { status: "inactive" }
 *     responses:
 *       200: { description: Updated; resData is the job category, content: { application/json: { schema: { $ref: '#/components/schemas/SuccessResponse' } } } }
 *       400: { description: "Validation error, job_category_exists (names are unique, deleted rows included)", content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *       401: { description: Missing or invalid token, content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *       403: { description: Not an admin, content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *       404: { description: Not found (job_category_not_found), content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *   delete:
 *     summary: Delete a job category (admin, soft delete)
 *     description: Refused with job_category_in_use while anything live uses it; mark it inactive instead.
 *     tags: [Master]
 *     security:
 *       - bearerAuth: []
 *     responses:
 *       200: { description: Deleted, content: { application/json: { schema: { $ref: '#/components/schemas/SuccessResponse' } } } }
 *       400: { description: In use (job_category_in_use), content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *       401: { description: Missing or invalid token, content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *       403: { description: Not an admin, content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 *       404: { description: Not found (job_category_not_found), content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
 */

